/* ARCO — local test demo
 *
 * Runs the REAL app code — the very modules index.html loads (model, layout,
 * render, tokens, figconv, components, plugins, …) — through a series of
 * checks and reports pass/fail right in the page.
 *
 * Works two ways:
 *   1. served:   python3 -m http.server 8080  →  http://localhost:8080/test-demo.html
 *   2. offline:  double-click this file (file://) — check 12 (fixtures over
 *                http) skips itself; everything else is self-contained, and
 *                the real Figma .fig used in check 2 is EMBEDDED below.
 */
(function () {
  'use strict';

  // circle.fig — a REAL Figma-exported .fig (v101: FRAME + red ELLIPSE,
  // solid fill + stroke), 32 KB, base64-embedded so the import check runs
  // with zero network access. Source: figlib/ref/real/circle.fig
  const CIRCLE_FIG_B64 = '';

  function b64ToBytes(b64) {
    const bin = atob(b64);
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  }

  function walk(page, id, fn) {
    const n = page.nodes[id];
    if (!n) return;
    fn(n);
    for (const cid of n.children) walk(page, cid, fn);
  }

  function hexRgb(hex) {
    const m = /^#?([0-9a-f]{6})$/i.exec(hex || '');
    if (!m) return null;
    return { r: parseInt(m[1].slice(0, 2), 16), g: parseInt(m[1].slice(2, 4), 16), b: parseInt(m[1].slice(4, 6), 16) };
  }

  const checks = [
    // ---------------------------------------------------------------- 1
    {
      name: '.fig codec loaded (kiwi/ZIP bundle + vector codec)',
      run: () => {
        const F = window.FigIO;
        const ok = !!F && typeof F.parseFigFile === 'function' && typeof F.writeFig === 'function'
          && typeof F.commandsBlobToPath === 'function' && typeof F.pathToVectorNetworkBlob === 'function'
          && typeof F.pathToCommandsBlob === 'function';
        return { ok, detail: ok
          ? 'parseFigFile · writeFig · commandsBlob/vectorNetworkBlob ⇄ SVG path — all present'
          : 'FigIO bundle is missing expected exports' };
      },
    },

    // ---------------------------------------------------------------- 2
    {
      name: 'Real Figma .fig import — embedded circle.fig (v101)',
      run: () => {
        const rep = window.FigConv.importFig(b64ToBytes(CIRCLE_FIG_B64));
        let frame = null, ellipse = null;
        rep.doc.pages.forEach(p => p.tops.forEach(t => walk(p, t, n => {
          if (n.type === 'frame') frame = n;
          if (n.type === 'ellipse') ellipse = n;
        })));
        const fill = ellipse && ellipse.fills && ellipse.fills[0];
        const rgb = fill && hexRgb(fill.color);
        const ok = !!frame && !!ellipse && fill && fill.type === 'solid'
          && rgb && rgb.r > 200 && rgb.g < 90 && rgb.b < 90;
        return { ok, detail: ok
          ? 'FRAME + ELLIPSE imported 1:1 — solid red fill, exact size/position from the kiwi message'
          : `expected FRAME + red ELLIPSE, got ellipse=${!!ellipse} fill=${fill && fill.color}` };
      },
    },

    // ---------------------------------------------------------------- 3
    {
      name: 'Auto-layout engine — measure→distribute→place (NOT flexbox)',
      run: () => {
        const M = window.Model, L = window.Layout;
        const doc = M.newDoc('al-check');
        const page = doc.pages[0];
        const f = M.makeNode('frame', { w: 600, h: 200, x: 0, y: 0, name: 'AL frame' });
        M.attach(doc, page, null, f);
        const al = M.makeAutoLayout(f, 'h', page);
        al.gap = { n: 15, tok: null };
        al.pad = [{ n: 10, tok: null }, { n: 20, tok: null }, { n: 10, tok: null }, { n: 30, tok: null }]; // t r b l
        const mk = (w, name) => {
          const n = M.makeNode('rect', { w, h: 40, name });
          M.attach(doc, page, f.id, n);
          M.ensureItemDefaults(page, f.id, n.id);
          return n;
        };
        const a = mk(80, 'A'), b = mk(100, 'B'), c = mk(60, 'C');
        b.als.w = 'fill'; b.als.grow = 1; // fill takes the remaining space
        L.layoutPage(page);
        // the engine resolves sizes into n._res and stores child x/y relative
        // to the parent (frame sits at 0,0, so absolute == relative here)
        const ok = a.x === 30 && a.y === 10 && a._res.w === 80
          && b.x === 125 && b._res.w === 380
          && c.x === 520 && c._res.w === 60;
        return { ok, detail: ok
          ? 'A@x30(80) · B fill@x125(w380) · C@x520(60) — gap 15, pad 30/20, cross y10: computed by the engine, placed by absolute canvas coordinates'
          : `got A(${a.x},${a.y},w${a._res.w}) B(${b.x},w${b._res.w}) C(${c.x},w${c._res.w}) — expected A(30,10,80) B(125,380) C(520,60)` };
      },
    },

    // ---------------------------------------------------------------- 4
    {
      name: 'Vector round-trip through a REAL .fig (kiwi encode + decode)',
      run: () => {
        const M = window.Model;
        const doc = M.newDoc('vec-check');
        const page = doc.pages[0];
        const vec = M.makeNode('vector', { w: 100, h: 60, x: 10, y: 10, name: 'VecGlyph' });
        vec.path = 'M 0 60 L 0 0 C 30 0 70 0 100 0 L 50 60 Z M 20 20 L 40 20 L 30 40 Z';
        vec.windingRule = 'evenodd';
        vec.fills = [{ type: 'solid', color: '#111111', opacity: 1, token: null }];
        M.attach(doc, page, null, vec);
        window.Layout.layoutPage(page);
        const bytes = window.FigConv.exportFig(doc);
        const parsed = window.FigIO.parseFigFile(bytes);
        const vnode = parsed.binary.message.nodeChanges.find(n => n.type === 'VECTOR' && n.name === 'VecGlyph');
        const hasBlobs = parsed.binary.message.blobs.length >= 1;
        const re = window.FigConv.importFig(bytes);
        let rv = null;
        re.doc.pages.forEach(p => p.tops.forEach(t => walk(p, t, n => { if (n.type === 'vector' && n.name === 'VecGlyph') rv = n; })));
        const ok = !!vnode && hasBlobs && !!rv && rv.path.startsWith('M 0.00 60.00') && rv.windingRule === 'evenodd';
        return { ok, detail: ok
          ? 'exported as VECTOR with commandsBlob + vectorNetworkBlob in message.blobs; re-imported path identical (f32-stable), even-odd rule kept'
          : `VECTOR=${!!vnode} blobs=${hasBlobs} reimport=${rv && rv.path && rv.path.slice(0, 16)}` };
      },
    },

    // ---------------------------------------------------------------- 5
    {
      name: 'SVG export — real <path> with fill-rule',
      run: () => {
        const M = window.Model;
        const doc = M.newDoc('svg-check');
        const page = doc.pages[0];
        const vec = M.makeNode('vector', { w: 100, h: 60, x: 0, y: 0, name: 'S' });
        vec.path = 'M 0 60 L 0 0 L 60 0 Z';
        vec.windingRule = 'evenodd';
        vec.fills = [{ type: 'solid', color: '#0d99ff', opacity: 1 }];
        M.attach(doc, page, null, vec);
        window.Layout.layoutPage(page);
        const svg = window.SvgExport.renderNode(doc, page, vec);
        const ok = svg.includes('<path d="M 0 60') && svg.includes('fill-rule="evenodd"');
        return { ok, detail: ok ? '<path d="…"> + fill-rule="evenodd" emitted for the vector node' : 'vector path missing from SVG output' };
      },
    },

    // ---------------------------------------------------------------- 6
    {
      name: 'PDF export — spec-valid 1.4 with real vector path ops',
      run: () => {
        const M = window.Model;
        const doc = M.newDoc('pdf-check');
        const page = doc.pages[0];
        const vec = M.makeNode('vector', { w: 100, h: 60, x: 0, y: 0, name: 'P' });
        vec.path = 'M 0 60 L 0 0 C 30 0 70 0 100 0 L 50 60 Z';
        vec.fills = [{ type: 'solid', color: '#111111', opacity: 1 }];
        M.attach(doc, page, null, vec);
        window.Layout.layoutPage(page);
        const out = window.PdfExport.renderNode(doc, page, vec);
        const ok = out.pdf.startsWith('%PDF-1.4') && / m /.test(out.pdf) && / c /.test(out.pdf);
        return { ok, detail: ok ? '%PDF-1.4 header + move/curve path operators for the vector (pure-JS writer, no libs)' : 'PDF output missing header or path operators' };
      },
    },

    // ---------------------------------------------------------------- 7
    {
      name: 'Design tokens — modes + live bake',
      run: () => {
        const M = window.Model, T = window.Tokens;
        const doc = M.newDoc('tok-check');
        const page = doc.pages[0];
        const modes = doc.vars.modes;
        const s = T.addSet(doc, 'brand');
        const v = T.addVar(doc, s.id, { name: 'accent', type: 'color', values: { [modes[0].id]: '#11aaff', [modes[1].id]: '#ff3355' } });
        const n = M.makeNode('rect', { w: 50, h: 50, name: 'token-fill' });
        n.fills = [{ type: 'solid', color: '#000000', opacity: 1, token: v.id }];
        M.attach(doc, page, null, n);
        const l = T.getValue(doc, v.id, modes[0].id);
        const d = T.getValue(doc, v.id, modes[1].id);
        T.bake(doc, page, modes[1].id);
        const ok = l === '#11aaff' && d === '#ff3355' && n.fills[0]._resolved === '#ff3355';
        return { ok, detail: ok
          ? `mode 1 = ${l}, mode 2 = ${d}; bake() resolved the token fill to the mode-2 value`
          : `got modes (${l}, ${d}), baked ${n.fills[0]._resolved}` };
      },
    },

    // ---------------------------------------------------------------- 8
    {
      name: 'Plugin sandbox — async arco API over whitelisted RPC',
      run: async () => {
        const M = window.Model, P = window.Plugins;
        const App = {
          doc: M.newDoc('plug-check'), sel: [], page: null,
          markDirty() { }, toast() { }, setSel(ids) { this.sel = ids || []; },
          history: { begin() { }, end() { } },
        };
        App.page = App.doc.pages[0];
        const rn = M.makeNode('rect', { x: 0, y: 0, w: 10, h: 10, name: 'plugin-target' });
        M.attach(App.doc, App.page, null, rn);
        const r = await P.run(`
          const doc = await arco.doc();
          const target = (await arco.listNodes()).find(x => x.name === 'plugin-target');
          await arco.setPos(target.id, 42, 43);
          const after = await arco.getNode(target.id);
          return 'doc=' + doc.name + ' moved to ' + after.x + ',' + after.y;
        `, App);
        let blocked = null;
        try { P.handleRpc(App, 'nukeEverything', []); } catch (e) { blocked = e.message; }
        const ok = r && r.ok === true && r.result === 'doc=plug-check moved to 42,43'
          && rn.x === 42 && rn.y === 43 && /blocked plugin call/.test(blocked || '');
        return { ok, detail: ok
          ? `ran in a ${r.sandbox === 'worker' ? 'sandboxed Web Worker (separate realm)' : 'LOCAL trusted realm (no Web Workers here)'} · host node actually moved to (42,43) · result "${r.result}" · unlisted RPC call blocked`
          : `ok=${r && r.ok} result=${r && JSON.stringify(r.result)} node=(${rn.x},${rn.y}) blocked=${blocked}` };
      },
    },

    // ---------------------------------------------------------------- 9
    {
      name: 'Components — source edit flows through instance update',
      run: () => {
        const M = window.Model, C = window.Components;
        const doc = M.newDoc('comp-check');
        const page = doc.pages[0];
        const cf = M.makeNode('frame', { w: 200, h: 80, x: 0, y: 0, name: 'Button' });
        M.attach(doc, page, null, cf);
        const cr = M.makeNode('rect', { w: 60, h: 30, x: 20, y: 25, name: 'bg' });
        cr.fills = [{ type: 'solid', color: '#2288ff', opacity: 1 }];
        M.attach(doc, page, cf.id, cr);
        const comp = C.makeComponent(doc, page, cf.id, 'Button');
        const compId = comp && comp.id; // makeComponent returns the set object
        const inst = C.makeInstance(doc, page, compId, 'Button', 300, 300);
        cr.fills[0].color = '#ff9900'; // edit the SOURCE
        C.updateAny(doc, page, inst.id);
        let instRect = null;
        walk(page, inst.id, n => { if (n.type === 'rect') instRect = n; });
        const ok = !!compId && !!inst && !!instRect && instRect.fills[0].color === '#ff9900'
          && C.list(doc).some(c => c.id === compId);
        return { ok, detail: ok
          ? 'component registered · instance stamped · source color #2288ff→#ff9900 flowed into the instance on update'
          : `comp=${!!compId} inst=${!!inst} instRect=${!!instRect} color=${instRect && instRect.fills[0] && instRect.fills[0].color}` };
      },
    },

    // ---------------------------------------------------------------- 10
    {
      name: 'Persistence — save, flush, re-read from the durable backend',
      run: async () => {
        const M = window.Model, st = M.store;
        await st.init();
        const backend = st.backend;
        if (backend === 'memory') {
          return { ok: true, skip: true, detail: 'skipped — this context offers no IndexedDB or localStorage (opaque origin?)' };
        }
        const d = M.newDoc('persist-check');
        st.put({ id: 'demo-persist-check', name: 'persist-check', createdAt: Date.now(), updatedAt: Date.now(), pageCount: 1, thumb: '', doc: d });
        await st.flush();
        await st.init(true); // force re-read from the durable backend
        const found = st.all().find(f => f.id === 'demo-persist-check');
        const ok = !!found && !!found.doc && found.doc.name === 'persist-check' && found.doc.pages.length === 1;
        if (found) { st.remove('demo-persist-check'); await st.flush(); } // keep the demo re-runnable
        const where = backend === 'idb' ? 'IndexedDB' : 'localStorage';
        return { ok, detail: ok
          ? `saved → flushed → re-read from ${where}: the whole document came back intact (test entry cleaned up)`
          : 'document did not survive the forced re-read' };
      },
    },

    // ---------------------------------------------------------------- 11
    {
      name: 'Constraints + resize-to-fit',
      run: () => {
        const M = window.Model, L = window.Layout;
        const doc = M.newDoc('con-check');
        const page = doc.pages[0];
        const f = M.makeNode('frame', { w: 100, h: 100, x: 0, y: 0, name: 'constrained' });
        M.attach(doc, page, null, f);
        const left = M.makeNode('rect', { w: 20, h: 20, x: 5, y: 40, name: 'L' });
        left.constraints = { h: 'min', v: 'center' };
        const right = M.makeNode('rect', { w: 20, h: 20, x: 75, y: 40, name: 'R' });
        right.constraints = { h: 'max', v: 'min' };
        M.attach(doc, page, f.id, left);
        M.attach(doc, page, f.id, right);
        f.w = 200; f.h = 150;
        L.applyConstraints(page, f, 100, 100);
        const okA = left.x === 5 && left.y === 65 && right.x === 175 && right.y === 40;
        const g = M.makeNode('frame', { w: 500, h: 400, x: 0, y: 0, name: 'r2f' });
        M.attach(doc, page, null, g);
        const c1 = M.makeNode('rect', { w: 100, h: 50, x: 10, y: 20, name: 'kid' });
        M.attach(doc, page, g.id, c1);
        const r = L.resizeToFit(page, g);
        // resize-to-fit shrinks the frame in place onto its content
        const okB = !!r && g.w === 100 && g.h === 50;
        const ok = okA && okB;
        return { ok, detail: ok
          ? 'frame 100×100 → 200×150: center-constrained child moved +25y, max-constrained child +100x; resize-to-fit shrank a 500×400 frame onto its child (100×50)'
          : `constraints ok=${okA} (L ${left.x},${left.y} / R ${right.x},${right.y}) · resizeToFit ok=${okB} (${g.x},${g.y} ${g.w}×${g.h})` };
      },
    },

    // ---------------------------------------------------------------- 12
    {
      name: 'Real 9-vector Figma file (fetched — served mode only)',
      run: async () => {
        if (typeof fetch !== 'function') {
          return { ok: true, skip: true, detail: 'skipped — no fetch() available in this context' };
        }
        let res;
        try { res = await fetch('fixtures/word-outline-stroke.fig', { cache: 'no-store' }); }
        catch (e) {
          return { ok: true, skip: true, detail: 'skipped — served over file://; run via http to test this' };
        }
        if (!res.ok) {
          return { ok: true, skip: true, detail: `skipped — fixtures/word-outline-stroke.fig not found (${res.status}); serve the app from the arco/ folder` };
        }
        const bytes = new Uint8Array(await res.arrayBuffer());
        const rep = window.FigConv.importFig(bytes);
        let vecs = 0, withPath = 0;
        rep.doc.pages.forEach(p => p.tops.forEach(t => walk(p, t, n => {
          if (n.type === 'vector') { vecs++; if (n.path) withPath++; }
        })));
        const ok = vecs === 9 && withPath === 9;
        return { ok, detail: ok
          ? 'word-outline-stroke.fig: 9/9 vector glyphs imported with decoded paths (the full suite verifies bbox == node size for each)'
          : `expected 9 vectors with paths, got ${withPath}/${vecs}` };
      },
    },
  ];

  async function runAll(onProgress) {
    const results = [];
    for (const c of checks) {
      const t0 = Date.now();
      let r;
      try { r = await c.run(); }
      catch (e) { r = { ok: false, detail: 'threw: ' + (e && e.message ? e.message : String(e)) }; }
      r.ms = Date.now() - t0;
      results.push({ name: c.name, ok: !!r.ok, skip: !!r.skip, detail: r.detail || '', ms: r.ms });
      if (onProgress) onProgress(results.slice());
    }
    return results;
  }

  window.ARCODemo = { checks, runAll, b64ToBytes };
})();
